head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageSize = 50; // 페이지 size
scwin.totalCnt = 0; // 전체 row
scwin.pageNoCnt = 10; // page 번호 개수
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
scwin.gParamObj = new Array(2);
scwin.gDepCd = js_dep_cd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        scwin.setCode();
        scwin.initPage();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30312.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30312.btn_SDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_EDATE_onclick
 * @description btn_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30312.btn_EDATE_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30312.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30312.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name cmb_PerPage_onselchange2
 * @description cmb Per Page onselchange2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_PerPage_onselchange2 = async function() {
    try {
        const vPerPage = $c.cp.valueOfIndex(cmb_PerPage, "VALUE", cmb_PerPage.getSelectedIndex());
        scwin.pageSize = vPerPage;
        // alert(pageSize);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30312.cmb_PerPage_onselchange2" });
    }
};

/**
 * @method
 * @name cmb_PerPage_OnSelected
 * @description cmb Per Page On Selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PerPage_OnSelected = function() {

};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = async function(rowcount) {
    try {
        /*
        var vTotalCnt = dts_Grid.NameString(1, "CNT");
        //FillGridHeader2(pageNoCnt, getObjectValue(cmb_PerPage), vTotalCnt, panel_page);

        //alert(pageNoCnt +", "+getObjectValue(cmb_PerPage)+", "+vTotalCnt);
        //페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
        FillGridHeader(pageNoCnt, getObjectValue(cmb_PerPage), vTotalCnt, panel_page, 743);

         */

        if (dts_Grid.errorMsg) {
            await $c.win.alert("OnLoadCompleted Error => " + dts_Grid.errorMsg);
        } else {
            if (scwin.pageSize !== '0') {
                if (scwin.vCurrPageNo === 0) {
                    scwin.vCurrPageNo = 1;
                    scwin.totalCnt = dts_Grid.getCellData(0, "CNT");
                }
            } else {
                scwin.totalCnt = rowcount;
            }
            // alert(pageNoCnt +", "+pageSize+", "+totalCnt);
            // 페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
            $c.stf.FillGridHeader(scwin.pageNoCnt, scwin.pageSize, scwin.totalCnt, panel_page, 743);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30312.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30312.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        await scwin.openDetail(row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30312.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        await scwin.openNew(0, 'N');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30312.btn_New_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) === false) {
        return;
    }
    scwin.vCurrPageNo = 0;
    url += "&MDTYPE=1"; // 알림매체타입, 이메일= 1
    url += "&SDATE=" + edt_SDATE.getValue();
    url += "&EDATE=" + edt_EDATE.getValue();
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + scwin.pageSize;
    url += "&SCREN_ID=" + "ULDSTF30312.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/NoteMgt.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name PageNoCall
 * @description 현재 선택한 페이지번호
 * @param {*} vPageNo vPageNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.PageNoCall = async function(vPageNo) {
    // 현재 선택한 페이지번호
    scwin.vCurrPageNo = vPageNo;
    url += "&MDTYPE=1"; // 알림매체타입, 이메일= 1
    url += "&SDATE=" + edt_SDATE.getValue();
    url += "&EDATE=" + edt_EDATE.getValue();
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + scwin.pageSize;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/NoteMgt.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    $c.stf.comboCbDataSet(cmb_PerPage);
};

/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPage = function() {
    const ToDay = $c.ut.cGetToday2();
    edt_EDATE.setValue(ToDay);
    const vSDATE = $c.ut.calcMonth(ToDay, -6);
    edt_SDATE.setValue(vSDATE);
};

/**
 * @method
 * @name openNew
 * @description open New 처리
 * @param {Number} row 행 인덱스
 * @param {*} inAddTyp inAddTyp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openNew = async function(row, inAddTyp) {
    if (js_svrGubun === 'dr') {
        await $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        return;
    }
    let vNOTI_SVC_ID = '';
    if (inAddTyp === 'Y') {
        vNOTI_SVC_ID = dts_Grid.getCellData(row, "NOTI_SVC_ID");
    }
    let url = "";
    url = "/bizspt/ULDSTF30311.gfm?";
    url += "NOTI_SVC_ID=" + vNOTI_SVC_ID;
    url += "&ADD_INPUT=" + inAddTyp;
    url += "&frameID=" + frame.FrameID;
    if (await scwin.setParam(vNOTI_SVC_ID, inAddTyp)) {
        // formal arguments
        $c.frame.path("../../").GWinOpen("ULDSTF30311", url, "이메일 신규", 200, 10, 790, 750 + 30, "");
    }
    // frame.CreateFrame("SENDMAIL_NEW", "/bizspt/ULDSTF30311.gfm", "이메일 신규", 200, 10, 790, 750+30, "window",0,0,true);

};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row, colid) {
    if (colid === "TITLE") {
        let vNOTI_SVC_ID = dts_Grid.getCellData(row, "NOTI_SVC_ID");
        let url = "/bizspt/ULDSTF30313.gfm?";
        url += "NOTI_SVC_ID=" + vNOTI_SVC_ID;
        if (await scwin.setParam(vNOTI_SVC_ID)) {
            // formal arguments
            $c.frame.path("../../").GWinOpen("ULDSTF30313", url, "이메일 상세조회", 200, 10, 800, 630 + 40, "");
        }
        // frame.CreateFrame("SENDEMAIL_READ|NOTI_SVC_ID=" + vNOTI_SVC_ID, "/bizspt/ULDSTF30313.gfm", "이메일 상세조회", 200, 10, 790, 630+30, "window",0,0,true);

    } else if (colid === "INPUT") {
        await scwin.openNew(row, 'Y');
    }
};

/**
 * @method
 * @name setParam
 * @description child에 param을 넘긴다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) === "undefined") {
        await $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
